// UsdRelationship::HasAuthoredTargets: an authored targetPaths opinion,
// including an explicitly empty (or blocked) target list.
function _hasAuthoredTargets(prim: Prim, name: string): boolean {
  return prim.getStage().get(`${prim.path}.${name}`)?.hasAuthoredMetadata('targetPaths') ?? false
}

function _parentPrim(prim: Prim): Prim | undefined {
  const slash = prim.path.lastIndexOf('/')
  return prim.getStage().getPrim(slash <= 0 ? '/' : prim.path.slice(0, slash))
}

// _HasInactiveAncestor (bindingAPI.cpp:346-358).
function _hasInactiveAncestor(stage: Stage, path: string): boolean {
  if (path.startsWith('/')) {
    for (let p = path.slice(0, path.lastIndexOf('/')); p.length > 0; p = p.slice(0, p.lastIndexOf('/'))) {
      const prim = stage.getPrim(p)
      if (prim) return !prim.isActive
    }
  }
  return false
}

// _GetFirstTargetPrimForRel (bindingAPI.cpp:361-386).
function _getFirstTargetPrimForRel(prim: Prim, rel: UsdRel, targets: readonly string[]): Prim | undefined {
  if (targets.length > 0) {
    if (targets.length > 1) {
      TfWarn(`${rel.getPath()} -- relationship has more than one target. Only the first will be used.`)
    }
    const target = targets[0]!
    const targetPrim = prim.getStage().getPrim(target)
    if (targetPrim) return targetPrim
    // Should throw a warning about an invalid target. However, we may not
    // be able to access the prim because one of its ancestors may be
    // inactive. If so, failing to retrieve the prim is expected, so we
    // should avoid warning spam.
    if (!_hasInactiveAncestor(prim.getStage(), target)) {
      TfWarn(`${rel.getPath()} -- Invalid target <${target}>.`)
    }
  }
  return undefined
}

